"""Regenerates dagster_plus_schema_subset.graphql: the slice of the real Dagster+ GraphQL schema that the queries in
dagster_evidence_tools / dagster_discovery_tools use.

The source is dagster-cloud's app-cloud `schema.graphql` (Dagster+, NOT open source -- OSS accepts some fields Dagster+
rejects, e.g. `... on PythonError` under `assetChecksOrError`). Usage:

    python make_dagster_plus_schema_subset.py <path/to/app-cloud/src/graphql/schema.graphql> <git-sha-of-source>

Keeps only the root Query type's (CloudQuery) fields listed in ROOT_FIELDS and every type reachable from them.
"""
import sys
from pathlib import Path

from graphql import parse, print_ast
from graphql.language import ast

ROOT_FIELDS = ("assetNodes", "workspaceOrError", "runsOrError", "logsForRun", "alertPoliciesForCodeLocation")


def _named(t):
    while not isinstance(t, ast.NamedTypeNode):
        t = t.type
    return t.name.value


def main(src: str, sha: str) -> None:
    doc = parse(Path(src).read_text())
    defs = {}
    for d in doc.definitions:
        name = getattr(getattr(d, "name", None), "value", None)
        if name and not isinstance(d, ast.DirectiveDefinitionNode):
            defs.setdefault(name, d)
    root = next(d for d in doc.definitions if isinstance(d, ast.SchemaDefinitionNode))
    root_name = next(t.type.name.value for t in root.operation_types if t.operation.value == "query")
    query = defs[root_name]
    query = ast.ObjectTypeDefinitionNode(
        name=query.name, interfaces=query.interfaces, directives=(), description=None,
        fields=tuple(f for f in query.fields if f.name.value in ROOT_FIELDS))
    assert len(query.fields) == len(ROOT_FIELDS), [f.name.value for f in query.fields]
    defs[root_name] = query

    def refs(d):
        out = []
        for f in getattr(d, "fields", None) or ():
            out.append(_named(f.type))
            out += [_named(a.type) for a in (getattr(f, "arguments", None) or ())]
        for u in getattr(d, "types", None) or ():
            out.append(u.name.value)
        out += [i.name.value for i in getattr(d, "interfaces", None) or ()]
        return out

    keep, todo = {}, [root_name]
    while todo:
        n = todo.pop()
        if n in keep or n not in defs:
            continue
        keep[n] = defs[n]
        todo += refs(keep[n])
    # interfaces' implementers matter for `... on Type` fragments on interface fields
    for n, d in list(defs.items()):
        if isinstance(d, ast.ObjectTypeDefinitionNode) and any(i.name.value in keep for i in d.interfaces or ()):
            todo.append(n)
    while todo:
        n = todo.pop()
        if n in keep or n not in defs:
            continue
        keep[n] = defs[n]
        todo += refs(keep[n])
    header = (f"# Subset of the Dagster+ GraphQL schema (dagster-cloud app-cloud schema.graphql @ internal {sha}).\n"
              f"# Generated by make_dagster_plus_schema_subset.py -- do not edit by hand.\n")
    body = f"schema {{\n  query: {root_name}\n}}\n\n" + "\n".join(print_ast(d) + "\n" for d in keep.values())
    out = Path(__file__).with_name("dagster_plus_schema_subset.graphql")
    out.write_text(header + body)
    print(f"wrote {out} ({len(keep)} types)")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
